arguments.command:
curl -s "https://www.googleapis.com/calendar/v3/calendars/primary/events?q=vendor&singleEvents=true&maxResults=250" -H "Authorization: Bearer <TOKEN>" | python3 -c "
import json,sys
d=json.load(sys.stdin)
for e in d.get('items',[]):
    if e.get('status')=='cancelled': continue
    for a in e.get('attendees',[]):
        if a.get('displayName')=='Dana Whitfield' and a.get('optional'):
            print('MATCH:',e['id'],'|',e['summary'],'|',e['start'])
print('done, total vendor events:',len(d.get('items',[])))
"

